<script setup lang="ts">
import { ArrowLeft, Plus, Save, Sparkles, Trash2, Zap } from "lucide-vue-next";
import {
  PROJECTILE_VISUAL_KINDS,
  type ProjectileVisualKind,
  type TowerVisualEffectDefinition,
} from "~/components/tower-defense/scene/tower-models";
import type { TowerKind } from "~/types/games/towerDefense";
interface Tower { id:string; template_key:TowerKind; name:string; color:string; max_level:number; range:number; model_asset_keys:Record<string,string>; model_configuration:{targetHeight?:number;targetHeightByLevel?:Record<string,number>;visualEffects?:TowerVisualEffectDefinition[]}|null }
const api=useApi();const towers=ref<Tower[]>([]);const selectedTowerId=ref("");const previewLevel=ref(1);const effects=ref<TowerVisualEffectDefinition[]>([]);const loading=ref(true);const saving=ref(false);const error=ref("");const message=ref("");
const selectedTower=computed(()=>towers.value.find(tower=>tower.id===selectedTowerId.value));
const visualEffectsCode=ref("");const codeError=ref("");
const projectileKindLabels:Record<ProjectileVisualKind,string>={archer:"Mũi tên",cannon:"Đạn pháo",frost:"Tinh thể băng",fire:"Cầu lửa",thunder:"Tia sét",water:"Cầu nước"};
const projectileKindOptions=PROJECTILE_VISUAL_KINDS.map(kind=>({kind,label:projectileKindLabels[kind]}));
function defaultProjectileKind():ProjectileVisualKind{const kind=selectedTower.value?.template_key as ProjectileVisualKind;return PROJECTILE_VISUAL_KINDS.includes(kind)?kind:"fire"}
const assetUrl=(key?:string)=>key?"/api/tower-defense/assets/"+key.split("/").map(encodeURIComponent).join("/"):"";
const previewModelUrl=computed(()=>{const keys=selectedTower.value?.model_asset_keys??{};return assetUrl(keys["dark"+previewLevel.value]||keys.dark1||Object.values(keys).find(Boolean))});
function sanitizeVisualEffect(effect:TowerVisualEffectDefinition){const clean={...effect};if(clean.type==="projectile"){delete clean.glowColor;delete clean.trailLength;delete clean.trailOpacity;if(selectedTower.value?.template_key==="frost"){delete clean.heightRatio;delete clean.projectileKind;clean.size=1}}return clean}
function syncVisualEffectsCode(){visualEffectsCode.value="const visualEffects = "+JSON.stringify(effects.value.map(sanitizeVisualEffect),null,2)+";"}
function applyVisualEffectsCode(){codeError.value="";try{const source=visualEffectsCode.value.trim().replace(/^const\s+visualEffects\s*=\s*/,"").replace(/;\s*$/,"");const parsed:unknown=JSON.parse(source);if(!Array.isArray(parsed))throw new Error("Code phải trả về một mảng visualEffects.");if(!parsed.every(effect=>effect&&typeof effect==="object"&&(effect as {type?:unknown}).type!==undefined))throw new Error("Mỗi hiệu ứng phải là một object có thuộc tính type.");effects.value=(parsed as TowerVisualEffectDefinition[]).map(sanitizeVisualEffect);syncVisualEffectsCode()}catch(e){codeError.value=e instanceof Error?e.message:"Code hiệu ứng không hợp lệ."}}
function loadSelectedEffects(){previewLevel.value=1;effects.value=(selectedTower.value?.model_configuration?.visualEffects??[]).map(effect=>{const clean=sanitizeVisualEffect(effect);return clean.type==="projectile"?{...clean,...(selectedTower.value?.template_key==="frost"?{}:{projectileKind:selectedTower.value?.template_key==="thunder"?"thunder":clean.projectileKind??defaultProjectileKind(),heightRatio:clean.heightRatio??.9})}:clean})}
async function load(){loading.value=true;error.value="";try{const response=await api<{data:Tower[]}>("/api/admin/tower-defense/towers?per_page=500");towers.value=response.data;selectedTowerId.value=response.data[0]?.id??"";loadSelectedEffects()}catch(e:any){error.value=e?.data?.message||"Không thể tải danh sách tower."}finally{loading.value=false}}
function addGlow(){effects.value.push({id:"glow-"+Date.now(),type:"glow",enabled:true,level:0,color:selectedTower.value?.color??"#8b5cf6",heightRatio:.9,size:1,opacity:.7,pulseSpeed:4})}
function addProjectile(){const color=selectedTower.value?.color??"#8b5cf6";effects.value.push({id:"projectile-"+Date.now(),type:"projectile",enabled:true,level:0,...(selectedTower.value?.template_key==="frost"?{}:{projectileKind:defaultProjectileKind(),heightRatio:.9}),color,size:1,opacity:.9,pulseSpeed:8})}
function isGlow(effect:TowerVisualEffectDefinition){return effect.type==="glow"}
function removeEffect(index:number){effects.value.splice(index,1)}
async function save(){if(!selectedTower.value||saving.value)return;saving.value=true;error.value="";message.value="";try{await api("/api/admin/tower-defense/towers/"+selectedTower.value.id+"/visual-effects",{method:"PUT",body:{visual_effects:effects.value.map(sanitizeVisualEffect)}});selectedTower.value.model_configuration={...(selectedTower.value.model_configuration??{}),visualEffects:effects.value.map(sanitizeVisualEffect)};message.value="Đã lưu hiệu ứng hiển thị cho "+selectedTower.value.name+"."}catch(e:any){error.value=e?.data?.message||"Không thể lưu hiệu ứng hiển thị."}finally{saving.value=false}}
watch(selectedTowerId,loadSelectedEffects);watch(effects,syncVisualEffectsCode,{deep:true,immediate:true});useHead({title:"Hiệu ứng hiển thị Tower | Admin"});onMounted(load);
</script>
<template><main class="effect-type-page tower-visual-page"><header class="page-head"><div><NuxtLink to="/admin/tower-defense/towers"><ArrowLeft/> Quản lý tower</NuxtLink><small>TOWER VISUAL EFFECTS</small><h1>Hiệu ứng hiển thị trụ</h1><p>Tạo glow trên model và hiệu ứng đạn bắn hiển thị trực tiếp trong game.</p></div><div class="visual-actions"><button type="button" :disabled="!selectedTower" @click="addProjectile"><Zap/> Thêm hiệu ứng đạn</button><button class="primary" type="button" :disabled="!selectedTower" @click="addGlow"><Plus/> Thêm glow</button></div></header><p v-if="error" class="alert">{{error}}</p><p v-if="message" class="visual-success">{{message}}</p><div v-if="loading" class="empty">Đang tải…</div><template v-else><div class="visual-selectors"><label class="tower-selector"><span>Chọn tower</span><select v-model="selectedTowerId"><option v-for="tower in towers" :key="tower.id" :value="tower.id">{{tower.name}} ({{tower.id}})</option></select></label><label class="tower-selector"><span>Level preview</span><select v-model.number="previewLevel"><option v-for="level in selectedTower?.max_level" :key="level" :value="level">Level {{level}}</option></select></label></div><section v-if="selectedTower" class="visual-workspace"><div class="visual-preview"><ClientOnly><TowerDefenseEnemyModelPreview :model-url="previewModelUrl" :tower-kind="selectedTower.template_key" :tower-range="selectedTower.range" :visual-effects="effects" :visual-effect-level="previewLevel" :character-scale="1" :scene-scale="1" eyebrow="TOWER VISUAL PREVIEW" :title="selectedTower.name" :show-animation-controls="false" detail-label="Số hiệu ứng" :detail-value="String(effects.length)"/><template #fallback><div class="empty">Đang khởi tạo preview 3D…</div></template></ClientOnly></div><form class="visual-editor" @submit.prevent="save"><div v-if="!effects.length" class="visual-empty"><Sparkles/><strong>Chưa có hiệu ứng hiển thị</strong><span>Bấm “Thêm glow” hoặc “Thêm hiệu ứng đạn” để bắt đầu.</span></div><article v-for="(effect,index) in effects" :key="effect.id" class="visual-effect-card"><header><div><i :style="{background:effect.color}"/><span><small>{{effect.type==="projectile"?"PROJECTILE":"GLOW"}}</small><strong>{{effect.id}}</strong></span></div><button class="danger" type="button" :title="effect.type==='projectile'?'Xóa hiệu ứng đạn':'Xóa glow'" @click="removeEffect(index)"><Trash2/></button></header><div class="visual-fields"><label><span>{{effect.type==="projectile"?"Màu lõi đạn":"Màu glow"}}</span><input v-model="effect.color" type="color"/></label><label><span>Áp dụng level</span><select v-model.number="effect.level"><option :value="0">Tất cả level</option><option v-for="level in selectedTower.max_level" :key="level" :value="level">Level {{level}}</option></select></label><template v-if="isGlow(effect)"><label><span>Độ cao trên model</span><input v-model.number="effect.heightRatio" type="range" min="0" max="1.5" step="0.01"/><input v-model.number="effect.heightRatio" class="visual-number" type="number" min="0" max="1.5" step="0.01"/></label></template><template v-else><label v-if="selectedTower.template_key!=='frost'"><span>Độ cao điểm bắn trên model</span><input v-model.number="effect.heightRatio" type="range" min="0" max="1.5" step="0.01"/><input v-model.number="effect.heightRatio" class="visual-number" type="number" min="0" max="1.5" step="0.01"/></label><small v-else class="visual-field-note">Tháp băng không bắn projectile; sóng đóng băng dùng tầm bắn {{selectedTower.range}} ô từ cấu hình tower.</small><label v-if="selectedTower.template_key!=='frost'"><span>Hình dáng đạn FE</span><select v-model="effect.projectileKind" :disabled="selectedTower.template_key==='thunder'"><option v-for="option in projectileKindOptions" :key="option.kind" :value="option.kind">{{option.label}} ({{option.kind}})</option></select><small v-if="selectedTower.template_key==='thunder'">Tháp sét luôn dùng tia sét nối trực tiếp mục tiêu.</small></label></template><label v-if="isGlow(effect)||selectedTower.template_key!=='frost'"><span>Kích thước</span><input v-model.number="effect.size" type="range" min="0.05" max="5" step="0.05"/><input v-model.number="effect.size" class="visual-number" type="number" min="0.05" max="5" step="0.05"/></label><label><span>Độ sáng</span><input v-model.number="effect.opacity" type="range" min="0" max="1" step="0.01"/><input v-model.number="effect.opacity" class="visual-number" type="number" min="0" max="1" step="0.01"/></label><label><span>Tốc độ pulse</span><input v-model.number="effect.pulseSpeed" type="range" min="0" max="20" step="0.1"/><input v-model.number="effect.pulseSpeed" class="visual-number" type="number" min="0" max="20" step="0.1"/></label><label class="check"><input v-model="effect.enabled" type="checkbox"/> Hiển thị hiệu ứng</label></div></article><footer><button class="primary" type="submit" :disabled="saving"><Save/> {{saving?"Đang lưu…":"Lưu hiệu ứng"}}</button></footer></form></section><section v-if="selectedTower" class="visual-code"><header><div><small>JAVASCRIPT</small><strong>Code hiệu ứng hiện tại</strong></div></header><textarea v-model="visualEffectsCode" spellcheck="false" aria-label="Code hiệu ứng hiện tại" @keydown.ctrl.enter.prevent="applyVisualEffectsCode"></textarea><p v-if="codeError" class="visual-code-error">{{codeError}}</p><footer><small>Nhấn Ctrl+Enter hoặc nút bên cạnh để cập nhật preview.</small><button type="button" @click="applyVisualEffectsCode">Áp dụng code</button></footer></section></template></main></template>
<style scoped src="~/assets/css/pages/admin/tower-defense-effect-types.css"></style>
