lds .check input{width:auto}.visual-empty{display:grid;min-height:180px;place-items:center;align-content:center;gap:7px;border:1px dashed #ffffff18;border-radius:16px;color:#71717a}.visual-empty svg{width:30px}.visual-empty strong{color:#ddd}.visual-editor>footer{display:flex;justify-content:flex-end}.visual-success{padding:12px;border:1px solid #22c55e44;border-radius:10px;color:#86efac;background:#14532d22}.visual-actions{display:flex;flex-wrap:wrap;gap:9px}.visual-actions button{display:inline-flex;align-items:center;gap:7px;padding:10px 13px;border:1px solid #8b5cf655;border-radius:10px;color:#ddd6fe;background:#8b5cf614}.visual-actions svg{width:16px}.visual-code{margin-top:18px;overflow:hidden;border:1px solid #ffffff12;border-radius:16px;background:#09090e}.visual-code header{padding:13px 16px;border-bottom:1px solid #ffffff0d}.visual-code header div{display:grid;gap:3px}.visual-code header small{color:#a78bfa;font-size:10px;letter-spacing:.14em}.visual-code header strong{color:#e4e4e7}.visual-code textarea{display:block;width:100%;min-height:300px;max-height:520px;box-sizing:border-box;padding:16px;resize:vertical;border:0;outline:0;color:#c4b5fd;background:#07070b;font:12px/1.65 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;tab-size:2}.visual-code>footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 16px;border-top:1px solid #ffffff0d}.visual-code>footer small{color:#71717a}.visual-code>footer button{padding:8px 12px;border:1px solid #8b5cf655;border-radius:8px;color:#ddd6fe;background:#8b5cf614}.visual-code-error{margin:0;padding:10px 16px;border-top:1px solid #ef444433;color:#fca5a5;background:#7f1d1d22}@media(max-width:900px){.visual-workspace{grid-template-columns:1fr}.visual-preview{position:static}}
@media(max-width:600px){.visual-fields{grid-template-columns:1fr}}</style>
